// Write budget backstop (P1). Storefront writes use the shared storefront
// write budget above; any remaining mutating route (notably every admin
// mutation) gets the same 120/min default unless it already declared a
// tighter limit. Webhooks/provider callbacks and health probes are excluded:
// a provider retry storm must never receive a 429 from our own throttle.
$defaultWriteThrottle = 'throttle:' . max(1, (int) (\Siro\Core\Env::get('THROTTLE_WRITE_DEFAULT', '120') ?? '120')) . ',1';
$writeMethods = ['POST', 'PUT', 'PATCH', 'DELETE'];
$seenWriteRoutes = [];
foreach ($app->router->getRoutes() as $route) {
    $method = strtoupper($route['method']);
    if (!in_array($method, $writeMethods, true)) continue;
    $path = $route['path'];
    if ($path === '' || str_starts_with($path, '/health') || str_contains($path, '/webhooks/')) continue;
    $routeKey = $method . ' ' . $path;
    if (isset($seenWriteRoutes[$routeKey])) continue;
    $seenWriteRoutes[$routeKey] = true;
    // The generous storefront read budget is attached to most routes. Ignore
    // it when deciding whether a write-specific limit already exists.
    $mw = strtolower($route['middleware']);
    $writeOnly = str_replace(strtolower($storefrontReads), '', $mw);
    if (str_contains($writeOnly, 'throttle')) continue;
    $app->router->setRouteMiddleware($method, $path, [$defaultWriteThrottle]);
}
// Enabled extensions mount last under /api/ext/<vendor>/<name> (spec RULE-E4).
// Best effort: a broken extension is logged and skipped, core routes live on.
\App\Modules\Extension\Application\ExtensionRouteLoader::mount($app->router, $fe);
});
